if (!webhookData.notification_ids || !Array.isArray(webhookData.notification_ids)) {
  throw new Error('Missing or invalid notification_ids in webhook payload');
}

if (webhookData.notification_ids.length === 0) {
  throw new Error('Empty notification_ids array');
}

return [$input.first()];

// Extract notifications and calculate date range
const input = $input.first().json;

console.log('DEBUG: Input from Fetch Notifications:', JSON.stringify(input).substring(0, 500));

let notifications = input;

// Handle case where Supabase returns single object instead of array
if (!Array.isArray(notifications)) {
  if (notifications && typeof notifications === 'object') {
    notifications = [notifications];
  } else {
    throw new Error(`Invalid notifications format. Expected array or object, got: ${typeof notifications}`);
  }
}

if (notifications.length === 0) {
  throw new Error('No notifications found in database for provided IDs');
}

const unitIds = [...new Set(notifications.map(n => n.unit_id))];
const propertyIds = [...new Set(notifications.map(n => n.property_id))];

// Calculate dynamic date range: ±21 days from earliest/latest notification
const notifDates = notifications.map(n => new Date(n.start_date));
const notifEndDates = notifications.map(n => new Date(n.end_date));

const minDate = new Date(Math.min(...notifDates));
minDate.setDate(minDate.getDate() - 21); // 3 weeks before

const maxDate = new Date(Math.max(...notifEndDates));
maxDate.setDate(maxDate.getDate() + 21); // 3 weeks after

return [{
  json: {
    notifications: notifications,
    unit_ids: unitIds,
    property_ids: propertyIds,
    date_range: {
      from: minDate.toISOString().split('T')[0],
      to: maxDate.toISOString().split('T')[0]
    }
  }
}];

// Collect all data from merged inputs
const extractNode = $node["Extract IDs & Date Range"];
if (!extractNode || !extractNode.json) {
  throw new Error('Extract IDs & Date Range node failed or has no data');
}

const notifications = extractNode.json.notifications;
if (!notifications || notifications.length === 0) {
  throw new Error('No notifications data from Extract node');
}

// Merge node gives us 3 items: [availability_data, prices_data, units_data]
const mergedInputs = $input.all();
if (mergedInputs.length !== 3) {
  throw new Error(`Expected 3 inputs from Merge, got ${mergedInputs.length}`);
}

// Get data from each merged input
const availabilityData = mergedInputs[0].json;
const pricesData = mergedInputs[1].json;
const unitsData = mergedInputs[2].json;

const availability = Array.isArray(availabilityData) ? availabilityData : [availabilityData];
const prices = Array.isArray(pricesData) ? pricesData : [pricesData];
const units = Array.isArray(unitsData) ? unitsData : [unitsData];

// Enrich notifications with context
const enrichedNotifications = notifications.map(notif => {
  // Calculate gap size
  const gapStart = new Date(notif.start_date);
  const gapEnd = new Date(notif.end_date);
  const gapDays = Math.floor((gapEnd - gapStart) / (1000 * 60 * 60 * 24)) + 1;

  // Get surrounding availability (±21 days)
  const notifDate = new Date(notif.start_date);
  const before21 = new Date(notifDate);
  before21.setDate(before21.getDate() - 21);
  const after21 = new Date(notifDate);
  after21.setDate(after21.getDate() + 21);

  const surroundingAvail = availability
    .filter(a => {
      const aDate = new Date(a.date);
      return a.unit_id === notif.unit_id && aDate >= before21 && aDate <= after21;
    })
    .sort((a, b) => a.date.localeCompare(b.date))
    .map(a => `${a.date}: ${a.status}`);

  // Current restrictions for this date range
  const currentRestrictions = prices
    .filter(p =>
      p.unit_id === notif.unit_id &&
      p.date >= notif.start_date &&
      p.date <= notif.end_date
    );

  return {
    ...notif,
    gap_days: gapDays,
    surrounding_availability: surroundingAvail,
    current_cta: currentRestrictions[0]?.cta || 'brak',
    current_ctd: currentRestrictions[0]?.ctd || 'brak',
    current_min: currentRestrictions[0]?.min || 'brak'
  };
});

// Build Gemini prompt - SIMPLE strategy
const prompt = `Jesteś ekspertem od revenue management dla wynajmu krótkoterminowego w Polsce.

ZADANIE: Zaproponuj ustawienia CTA/CTD/MIN dla ${notifications.length} luk w dostępności.

STRATEGIA MIN-FIRST:
Celem jest wypełnienie luk DŁUŻSZYMI pobytami, nie blokowanie krótkich.

ZASADA:
1. Dzień 1 po rezerwacji → pusty (MIN=1, CTA=0, CTD=0)
   Pozwala przedłużyć poprzednią rezerwację

2. Dni 2-3 → restrykcje (MIN=3, CTA=7-14, CTD=0)
   Blokuje 1-2 dniowe bookings, wymusza minimum 3 noce

3. Reszta dni → flexible (MIN=2, CTA=0, CTD=0)
   Pozwala na długie pobyty

PRZYKŁAD (luka 5 dni):
[REZ] | Dzień 1: pusty | Dzień 2-3: MIN=3 | Dzień 4-5: MIN=2 | [REZ]

EFEKT:
❌ 1-2 dni: NIE (MIN=3 na dniach 2-3)
✅ Przedłużenie: TAK (dzień 1 pusty)
✅ 3+ dni: TAK (wypełnia lukę)
✅ Tydzień: TAK (zabiera całą lukę)

DANE O LUKACH:
${enrichedNotifications.map((n, i) => `
${i + 1}. ${n.property_name} - ${n.unit_name}
   Luka: ${n.start_date} do ${n.end_date} (${n.gap_days} dni)
   Obecne: CTA=${n.current_cta}, CTD=${n.current_ctd}, MIN=${n.current_min}

   Dostępność wokół (±21 dni):
   ${n.surrounding_availability.slice(0, 42).join('\n   ')}
`).join('\n')}

INSTRUKCJE:

DLA LUKI 1 DZIEŃ:
→ 1 suggestion: MIN=1, CTA=0, CTD=0
→ reasoning: "Pusty dzień pozwala przedłużyć poprzednią rezerwację o 1 dzień"

DLA LUKI 2 DNI:
→ Dzień 1: MIN=1, CTA=0, CTD=0 (pusty)
→ Dzień 2: MIN=3, CTA=10, CTD=0
→ reasoning: "Dzień 1 pusty na przedłużenie. Dzień 2 z MIN=3 blokuje dwudniówki ale pozwala na 3+"

DLA LUKI 3+ DNI:
→ Dzień 1: MIN=1, CTA=0, CTD=0 (pusty)
→ Dni 2-3: MIN=3, CTA=10, CTD=0 (restrykcje)
→ Reszta (jeśli jest): MIN=2, CTA=0, CTD=0 (flexible)
→ reasoning: "Strategiczne MIN wypełnia lukę dłuższymi pobytami, nie blokuje całkowicie"

WAŻNE:
- Zawsze 1 pusty dzień po rezerwacji
- MIN=3 na dniach 2-3 (główny mechanizm)
- Reszta flexible (MIN=2)
- CTA wspiera MIN (7-14 dni)
- Generuj OSOBNY suggestion dla KAŻDEGO dnia w luce

